package mx.jorge.despierta;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;
public final class ScheduleSetupActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);show();}
 void button(LinearLayout root,String label,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextColor(0xff10241e);b.setBackgroundTintList(null);GradientDrawable bg=new GradientDrawable();bg.setColor(0xffb9ef96);bg.setCornerRadius(36);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,140);lp.setMargins(0,16,0,0);root.addView(b,lp);b.setOnClickListener(v->run.run());}
 void show(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(36,60,36,40);root.setBackgroundColor(0xff10241e);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TextView t=new TextView(this);t.setTextColor(Color.WHITE);t.setTextSize(20);t.setText("Vigilancia solo en tu horario\n\nPara reactivarse sola con el teléfono bloqueado, Despierta necesita ubicación precisa con permiso Todo el tiempo y Alarmas y recordatorios.\n\nFuera del horario se detienen el GPS y el servicio. Al comenzar, Android reactiva la vigilancia.\n\nUbicación todo el tiempo: "+(Build.VERSION.SDK_INT<29||checkSelfPermission("android.permission.ACCESS_BACKGROUND_LOCATION")==0?"permitida":"pendiente")+"\nActivación exacta: "+(Build.VERSION.SDK_INT<31||getSystemService(AlarmManager.class).canScheduleExactAlarms()?"permitida":"pendiente"));root.addView(t);
 button(root,"Permitir ubicación todo el tiempo",()->{if(Build.VERSION.SDK_INT==29)requestPermissions(new String[]{"android.permission.ACCESS_BACKGROUND_LOCATION"},29);else DeviceCompatibility.open(this,new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));});
 button(root,"Permitir alarmas y recordatorios",()->{if(Build.VERSION.SDK_INT>=31)DeviceCompatibility.open(this,new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));});
 DeviceCompatibility.attach(this,root);
 button(root,"Aplicar y volver",()->{if(ScheduleController.permitted(this)){ScheduleController.sync(this);finish();}else Toast.makeText(this,"Faltan permisos. No se activó la programación automática.",Toast.LENGTH_LONG).show();});button(root,"Volver sin cambiar",()->finish());}
 protected void onResume(){super.onResume();show();}
}
